export type GalleryKey = keyof typeof galleryCopy

const plurals = new Intl.PluralRules("en")
const numbers = new Intl.NumberFormat("en")

export function t(key: GalleryKey): string {
  return galleryCopy[key]
}

export function tCount(
  keys: { one: GalleryKey; other: GalleryKey },
  count: number
): string {
  const key = plurals.select(count) === "one" ? keys.one : keys.other
  return galleryCopy[key].replace("{count}", numbers.format(count))
}
